package owl.nh;
import java.util.*;
import java.awt.*;
import java.awt.Point;
import java.awt.event.MouseEvent;
import net.runelite.api.*;
import net.runelite.api.widgets.Widget;

/** Uses the installed stretch listener without dispatching input; mechanics remain synthetic. */
public final class OlmUiHazardTests {
 static void check(boolean ok,String text){CoreTests.check(ok,"Olm UI/hazards: "+text);}
 public static void main(String[] args){
  Dimension real=new Dimension(765,503),displayed=new Dimension(1242,960);Point logical=new Point(603,302),scaled=VisibleCombatUi.scalePoint(logical,true,real,displayed);Map<String,Object> fields=new HashMap<>();fields.put("getRealDimensions",real);fields.put("getStretchedDimensions",displayed);Client client=ChambersTests.fake(Client.class,fields);
  net.runelite.client.plugins.stretchedmode.TranslateMouseListener listener=new net.runelite.client.plugins.stretchedmode.TranslateMouseListener(client);Canvas canvas=new Canvas();MouseEvent event=new MouseEvent(canvas,MouseEvent.MOUSE_MOVED,0,0,scaled.x,scaled.y,0,false);MouseEvent translated=listener.mouseMoved(event);check(translated.getX()==logical.x&&translated.getY()==logical.y,"scaled tab click survives the actual installed stretch translator");
  MouseEvent wrong=listener.mouseMoved(new MouseEvent(canvas,MouseEvent.MOUSE_MOVED,0,0,logical.x,logical.y,0,false));check(wrong.getX()!=logical.x&&wrong.getY()!=logical.y,"prior unscaled click demonstrably lands at the wrong game coordinate");check(VisibleCombatUi.scalePoint(logical,false,null,null).equals(logical),"unstretched coordinates remain unchanged");
  MouseEvent oldHelperEvent=new MouseEvent(canvas,MouseEvent.MOUSE_PRESSED,0,0,scaled.x,scaled.y,1,false,MouseEvent.BUTTON1);oldHelperEvent.setSource("unethicalite");boolean incompatible=false;try{listener.mousePressed(oldHelperEvent);}catch(ClassCastException e){incompatible=true;}check(incompatible,"installed old mouse helper source is incompatible with the installed stretch listener");
  for(MouseEvent click:VisibleCombatUi.clickEvents(canvas,scaled,0)){MouseEvent mapped;switch(click.getID()){case MouseEvent.MOUSE_PRESSED:mapped=listener.mousePressed(click);break;case MouseEvent.MOUSE_RELEASED:mapped=listener.mouseReleased(click);break;case MouseEvent.MOUSE_CLICKED:mapped=listener.mouseClicked(click);break;default:mapped=listener.mouseMoved(click);}check(mapped.getX()==logical.x&&mapped.getY()==logical.y&&mapped.getSource()==canvas,"every new click phase passes the actual installed translator with the correct coordinate and Component source");}
  check(VisibleCombatUi.layoutMatches("FIXED_VIEWPORT_INVENTORY_TAB",false,false)&&!VisibleCombatUi.layoutMatches("FIXED_VIEWPORT_INVENTORY_TAB",true,false),"inactive fixed tab cannot win over a resized tab");check(VisibleCombatUi.layoutMatches("RESIZABLE_VIEWPORT_BOTTOM_LINE_PRAYER_TAB",true,true)&&!VisibleCombatUi.layoutMatches("RESIZABLE_VIEWPORT_PRAYER_TAB",true,true),"active resized layout selects its own prayer button");
  Widget hidden=ChambersTests.fake(Widget.class,Collections.singletonMap("isVisible",false));Map<String,Object> childFields=new HashMap<>();childFields.put("isVisible",true);childFields.put("getParent",hidden);check(!VisibleCombatUi.effectivelyVisible(ChambersTests.fake(Widget.class,childFields)),"cached visible child under hidden interface cannot be clicked");
  OlmMechanicAdapter.Config config=new OlmMechanicAdapter.Config();check(OlmMechanicAdapter.bombObject(config,ObjectID.CRYSTAL_BOMB,null)&&!OlmMechanicAdapter.bombObject(config,30028,"Loot chest"),"installed bomb candidate excludes loot chest");check(OlmMechanicAdapter.electricGraphic(config,GraphicID.OLM_LIGHTNING)&&!OlmMechanicAdapter.electricGraphic(config,GraphicID.OLM_CRYSTAL),"lightning signal separated from crystal burst");check(OlmMechanicAdapter.electricObject(config,ObjectID.LIGHTNING,null)&&!OlmMechanicAdapter.namedFlame(config,"Electric wall"),"electric walls are avoided rather than clicked as flame walls");
  OlmSpecials policy=new OlmSpecials();OlmSpecials.View v=OlmSpecialsTests.view();v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.CRYSTAL_BOMB,4));OlmSpecials.Choice escape=policy.choose(v);check(escape.kind==OlmSpecials.Kind.MOVE&&escape.cell.distance(v.player)>0,"bomb radius containing all adjacent tiles must not cause a permanent hold");v.reachable.add(new OlmSpecials.Cell(5,0,0));escape=policy.choose(v);check(escape.kind==OlmSpecials.Kind.MOVE&&escape.cell.distance(v.player)>4,"full collision-checked route chooses outside the bomb radius");
  v=OlmSpecialsTests.view();v.hazards.add(new OlmSpecials.Hazard(v.player,OlmSpecials.HazardKind.ELECTRIC,0));v.hazards.add(new OlmSpecials.Hazard(new OlmSpecials.Cell(1,0,0),OlmSpecials.HazardKind.ELECTRIC,0));OlmSpecials.Choice dodge=policy.choose(v);check(dodge.kind==OlmSpecials.Kind.MOVE&&dodge.cell.equals(new OlmSpecials.Cell(0,1,0)),"leave electric lane through a free neighbouring tile");
  policy.requested(dodge,v.player,1);policy.observe(dodge.cell,2);new OlmSpecials().restoreLearning(policy.exportLearning());
  v=OlmSpecialsTests.view();v.player=new OlmSpecials.Cell(1,0,0);v.reachable.clear();v.reachable.add(new OlmSpecials.Cell(2,0,0));v.hazards.add(new OlmSpecials.Hazard(new OlmSpecials.Cell(0,0,0),OlmSpecials.HazardKind.ELECTRIC,config.electricRadius));check(policy.choose(v).cell.equals(new OlmSpecials.Cell(2,0,0)),"electric buffer triggers avoidance before standing on the wall tile itself");
  System.out.println("Olm UI/hazard checks passed: actual stretch translation, active tab layout, hidden parents, bomb-radius escape, electric-lane avoidance and learning roundtrip. No live inputs.");
 }
}
